package com.saedarm.overclock;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.Preferences;
import com.badlogic.gdx.audio.Music;
import com.badlogic.gdx.audio.Sound;
import com.badlogic.gdx.files.FileHandle;
import com.badlogic.gdx.math.MathUtils;
import com.badlogic.gdx.utils.ObjectMap;

/**
 * All sound in one place. Static so gameplay code can just call Sfx.at(...).
 * Sounds are generated by tools/make_sfx.py into assets/sfx.
 * Sounds from other racers get quieter with track distance from the player.
 */
public final class Sfx {
    public static final String BEEP = "beep", GO = "go", PICKUP = "pickup", MISSILE = "missile", MINE = "mine",
            HIT = "hit", KO = "ko", TURBO = "turbo", SHIELD = "shield", LOCK = "lock", SCRAPE = "scrape";
    private static final String[] ALL = {BEEP, GO, PICKUP, MISSILE, MINE, HIT, KO, TURBO, SHIELD, LOCK, SCRAPE,
            "engine", "recharge"};
    private static final float HEAR_RANGE = 250f;   // metres along the track

    private static final ObjectMap<String, Sound> sounds = new ObjectMap<>();
    private static Track track;
    private static Racer listener;
    private static long engineId = -1, rechargeId = -1;
    private static float rechargeVol, scrapeTimer;
    public static float volume = 0.8f;
    public static float musicVolume = 0.45f;
    public static boolean musicOn = true;
    private static Music music;
    private static String musicName;
    private static Preferences prefs;

    private Sfx() {}

    public static void load() {
        for (String n : ALL) sounds.put(n, Gdx.audio.newSound(Gdx.files.internal("sfx/" + n + ".wav")));
        prefs = Gdx.app.getPreferences("overclock");
        musicOn = prefs.getBoolean("music", true);
    }

    // ---------------------------------------------------------------- music

    /** Loop assets/music/<name>.ogg (falls back to menu.ogg). Keeps playing if it's already the current song. */
    public static void playMusic(String name) {
        FileHandle f = Gdx.files.internal("music/" + name + ".ogg");
        if (!f.exists()) { name = "menu"; f = Gdx.files.internal("music/menu.ogg"); }
        if (!name.equals(musicName)) {
            if (music != null) music.dispose();
            music = f.exists() ? Gdx.audio.newMusic(f) : null;
            musicName = name;
            if (music == null) return;
            music.setLooping(true);
            music.setVolume(musicVolume * volume);
        }
        if (music != null && musicOn && !music.isPlaying()) music.play();
    }

    /** M key: turn music on/off; remembered between sessions. */
    public static void toggleMusic() {
        musicOn = !musicOn;
        if (prefs != null) { prefs.putBoolean("music", musicOn); prefs.flush(); }
        if (music == null) return;
        if (musicOn) music.play(); else music.pause();
    }

    public static void play(String name, float vol) {
        Sound s = sounds.get(name);
        if (s != null && vol > 0.01f) s.play(vol * volume);
    }

    public static void play(String name) { play(name, 1f); }

    /** Play a sound that happens at track distance s; fades with distance from the player. */
    public static void at(String name, float s, float vol) {
        if (track == null || listener == null) { play(name, vol); return; }
        float d = Math.abs(track.delta(s, listener.s));
        play(name, vol * MathUtils.clamp(1f - d / HEAR_RANGE, 0f, 1f));
    }

    /** Start engine + recharge loops for a race. */
    public static void startRace(Track t, Racer player) {
        stopLoops();
        track = t;
        listener = player;
        Sound e = sounds.get("engine"), r = sounds.get("recharge");
        if (e != null) engineId = e.loop(0f);
        if (r != null) rechargeId = r.loop(0f);
        rechargeVol = 0;
    }

    /** Called every frame: engine pitch follows speed, recharge hum fades in on the strip. */
    public static void update(float dt, Racer p) {
        Sound e = sounds.get("engine"), r = sounds.get("recharge");
        float k = Math.min(1.6f, p.speed / Racer.MAX_SPEED);
        if (e != null && engineId != -1) {
            float pitch = 0.55f + 0.9f * k + (p.turbo > 0 ? 0.25f : 0f);
            e.setPitch(engineId, MathUtils.clamp(pitch, 0.5f, 2f));
            e.setVolume(engineId, p.respawn > 0 ? 0f : (0.18f + 0.22f * Math.min(1f, k)) * volume);
        }
        float target = p.inPit && p.energy < 100f ? 0.35f : 0f;
        rechargeVol = MathUtils.lerp(rechargeVol, target, Math.min(1f, 8f * dt));
        if (r != null && rechargeId != -1) r.setVolume(rechargeId, rechargeVol * volume);

        scrapeTimer -= dt;
        if (p.scraping && p.speed > 30f && scrapeTimer <= 0) {
            play(SCRAPE, 0.35f);
            scrapeTimer = 0.1f;
        }
    }

    public static void stopLoops() {
        Sound e = sounds.get("engine"), r = sounds.get("recharge");
        if (e != null) e.stop();
        if (r != null) r.stop();
        engineId = rechargeId = -1;
        track = null;
        listener = null;
    }

    public static void dispose() {
        if (music != null) music.dispose();
        music = null;
        musicName = null;
        for (Sound s : sounds.values()) s.dispose();
        sounds.clear();
    }
}
